`src/envs/dev/infra/logs.ts`
```typescript
import { ReaderIam, SecureBucket } from "../../../composites/index.js";

const ENV = "dev";
const REGION = "us-east-1";

export const logs = SecureBucket({
  name: "myapp-logs-dev",
  env: ENV,
  region: REGION,
});

export const logsReader = ReaderIam({
  name: "myapp-dev-logs",
  env: ENV,
  bucketName: "myapp-logs-dev",
  trust: { mode: "account", accountID: "123456789012" },
  additionalActions: ["s3:PutObject"],
  programmaticAccess: true,
});
```

`src/envs/prod/infra/logs.ts`
```typescript
import { ReaderIam, SecureBucket } from "../../../composites/index.js";

const ENV = "prod";
const REGION = "us-east-1";
const APP_NAMESPACE = "app";
const SERVICE_ACCOUNT = "myapp";

export const logs = SecureBucket({
  name: "myapp-logs-prod",
  env: ENV,
  region: REGION,
});

export const logsReader = ReaderIam({
  name: "myapp-prod-logs",
  env: ENV,
  bucketName: "myapp-logs-prod",
  trust: {
    mode: "oidc",
    providerARN: "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEPROD",
    issuerHost: "oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEPROD",
    serviceAccountNamespace: APP_NAMESPACE,
    serviceAccountName: SERVICE_ACCOUNT,
  },
  additionalActions: ["s3:PutObject"],
  programmaticAccess: false,
  podIdentity: {
    clusterName: "myapp-prod",
    serviceAccountNamespace: APP_NAMESPACE,
    serviceAccountName: SERVICE_ACCOUNT,
  },
});
```

**Summary:**

Each new file declares:

1. **`logs`** — a `SecureBucket` with automatic versioning, encryption (AES-256), and public-access blocking per the SPEC. The bucket names are `myapp-logs-dev` and `myapp-logs-prod`.

2. **`logsReader`** — a `ReaderIam` identity scoped only to the corresponding logs bucket:
   - `additionalActions: ["s3:PutObject"]` grants write access to the logs bucket (alongside the baseline `s3:GetObject` and `s3:ListBucket`)
   - **Dev:** Uses account-based trust (`{ mode: "account", accountID: "123456789012" }`) with programmatic IAM user access, matching the existing `reader` pattern
   - **Prod:** Uses OIDC trust pinning both the service-account subject and STS audience, with `podIdentity` binding, matching the existing `reader` pattern

Both files use the composite factories idiomatically — no hand-written raw resources — and are discovered automatically by `chant build src/envs/{env}/infra` since they live under the respective `infra/` directories.
